const scenario =
  $input.first().json.query?.scenario || "v1_ok";
const attempt = Number($input.first().json.query?.attempt ?? 1);

// Synthetic customer records.
// No real customer information is used.
const original = [
  {
    customer_id: "C001",
    email: "alice@example.com",
    credit_limit: 5000,
    updated_at: "2026-11-17T09:00:00Z"
  },
  {
    customer_id: "C002",
    email: "bob@example.com",
    credit_limit: 7500,
    updated_at: "2026-11-17T09:00:00Z"
  },
  {
    customer_id: "C003",
    email: "carol@example.com",
    credit_limit: 3000,
    updated_at: "2026-11-17T09:00:00Z"
  }
];

let items = original.map(record => ({ ...record }));

switch (scenario) {
  case "v1_ok":
    // Expected contract: all required fields are valid.
    break;

  case "v2_rename":
    // Breaking change: customer_id is missing.
    items = items.map(({ customer_id, ...rest }) => ({
      id: customer_id,
      ...rest
    }));
    break;

  case "v2_type_drift":
    // Breaking change: number becomes string.
    items[0].credit_limit = "5000";
    break;

  case "empty_200":
    // HTTP success but contradictory business data.
    items = [];
    break;

  case "null_email":
    // Invalid null in a required, non-nullable field.
    items[0].email = null;
    break;

  case "v2_additive":
    // Non-breaking additional optional field.
    items = items.map(record => ({
      ...record,
      segment: "retail"
    }));
    break;


case "down_503":
  return [{
    json: {
      scenario: "down_503",
      error: "Partner API temporarily unavailable",
      simulated_http_status: 503
    }
  }];

case "rate_429":
  return [{
    json: {
      scenario: "rate_429",
      error: "Too many requests",
      simulated_http_status: 429
    }
  }];

case "rate_429_once":
  if (attempt === 1) {
    return [{
      json: {
        scenario: "rate_429_once",
        error: "Rate limit exceeded. Retry the request.",
        simulated_http_status: 429,
        attempt: 1
      }
    }];
  }
  break;


  default:
    throw new Error(`Unknown scenario: ${scenario}`);
}

return [
  {
    json: {
      connector_id: "partner_alpha",
      version: scenario.startsWith("v2_") ? "v2" : "v1",
      scenario,
      total_count: 3,
      items
    }
  }
];
